'use strict';
const $=id=>document.getElementById(id),h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
const price=n=>n==null?'—':'$'+Number(n).toPrecision(6),when=t=>t?new Date(t*1000).toLocaleTimeString(): '—',sign=n=>n>=0?'positive':'negative';
let state=null,runs=[],datasets=[],walletAddress=null,quote=null,walletStatus=null,busy=false,view='paper',assetsReady=false,signing=false,quoteGeneration=0;
function error(e){$('error').textContent=e.message||String(e);$('error').hidden=false;}
function message(s){$('message').textContent=s;$('message').hidden=false;}
async function api(path,body){const r=await fetch('/api/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data;}
async function act(action,body={}){if(busy)return;busy=true;$('error').hidden=true;try{render(await api(action,body));await refreshRuns();}catch(e){error(e);}finally{busy=false;}}
function render(s){state=s;$('connection').textContent='● Connected locally';$('status').textContent=s.completed?'Complete':s.running?'Running':'Paused';$('dot').className='dot'+(s.running?' running':'');$('clock').textContent=when(s.timestamp)+' · '+s.tick+' observations';$('toggle').textContent=s.running?'Pause paper bot':'Start paper bot';$('toggle').disabled=s.completed;$('step').disabled=s.running||s.completed;$('new').disabled=s.running;
$('source-title').textContent=s.mode==='demo'?'Synthetic demo':'Recorded data replay';$('source-note').textContent=`${s.dataset_source} · Virtual cash and hypothetical fills. ${s.source_error||''}`;
$('equity').textContent=money(s.equity);$('cash').textContent=money(s.cash);$('pnl').textContent=money(s.realized_pnl);$('pnl').className=sign(s.realized_pnl);$('positions-count').textContent=Object.keys(s.positions).length;$('trade-count').textContent=s.fills.filter(f=>f.side==='SELL').length+' closed trades';$('drawdown').textContent='Max drawdown '+(s.max_drawdown*100).toFixed(2)+'%';$('session').textContent=s.name+' · '+s.id.slice(0,8)+' · auto-saved';
const symbols=Object.keys(s.last),select=$('symbol'),previous=select.value;if([...select.options].map(o=>o.value).join('|')!==symbols.join('|')){select.innerHTML=symbols.map(x=>`<option>${h(x)}</option>`).join('');if(symbols.includes(previous))select.value=previous;}
$('position-cards').innerHTML=Object.entries(s.positions).map(([symbol,p])=>{const r=s.last[symbol],value=r&&(r.liquidity||0)>0&&s.timestamp-r.timestamp<=s.config.max_age?p.quantity*r.price*(1-s.config.slippage_bps/1e4)*(1-s.config.fee_bps/1e4):0;return `<button class="position-card" data-symbol="${h(symbol)}"><b>${h(symbol)}</b><span class="${sign(value-p.cost)}">${money(value-p.cost)}</span><span>${h(s.pending[symbol]?.status||'Open')}</span></button>`;}).join('')||'<p>No open positions. Select a token from the chart after observations arrive.</p>';
$('strategy-version').textContent=s.strategy_version;const c=s.config;$('rules').innerHTML=[['Allocation',money(c.size)],['Momentum lookback',c.lookback_seconds+' seconds'],['Entry change',c.momentum*100+'%'],['Minimum liquidity',money(c.min_liquidity)],['Position limit',c.max_positions],['Maximum hold',c.max_hold_seconds+' seconds'],['Order expiry',c.order_ttl+' seconds'],['Take profit / stop loss',c.take_profit*100+'% / '+c.stop_loss*100+'%'],['Fee / slippage per side',c.fee_bps+' / '+c.slippage_bps+' bps']].map(([a,b])=>`<div class="rule"><span>${h(a)}</span><b>${h(b)}</b></div>`).join('');
$('trades').innerHTML=s.fills.slice().reverse().map(f=>`<tr><td>${when(f.timestamp)}</td><td>${h(f.symbol)}</td><td>${f.side}</td><td>${price(f.price)}</td><td class="${sign(f.details.pnl||0)}">${f.details.pnl==null?'—':money(f.details.pnl)}</td><td>${h(f.details.reason)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No fills yet.</td></tr>';
$('orders').innerHTML=s.orders.map(o=>`<tr><td>${h(o.symbol)}</td><td>${o.side}</td><td>${h(o.status)}</td><td>${h(o.reason)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No orders yet.</td></tr>';
$('events').innerHTML=s.events.map(e=>`<div class="event ${e.kind==='warning'?'warning':''}"><time>${when(e.timestamp)}</time><span>${h(e.message)}</span></div>`).join('');chart();}
function chart(){if(!state)return;const sym=$('symbol').value,seconds=Number($('timeframe').value),rows=state.observations.filter(r=>r.symbol===sym),bars=new Map();for(const r of rows){const key=Math.floor(r.timestamp/seconds)*seconds;if(!bars.has(key))bars.set(key,{open:r.price,high:r.price,low:r.price,close:r.price});const b=bars.get(key);b.close=r.price;b.high=Math.max(b.high,r.price);b.low=Math.min(b.low,r.price);}
const all=[...bars.entries()],last=all.at(-1)?.[0]||0,first=Math.max(all[0]?.[0]||0,last-seconds*49),visible=all.filter(([t])=>t>=first),vals=visible.flatMap(([,b])=>[b.low,b.high]),low=vals.length?Math.min(...vals)*.96:0,high=vals.length?Math.max(...vals)*1.04:1,y=p=>210-(p-low)/(high-low||1)*180,x=t=>18+(t-first)/(Math.max(seconds,last-first))*690;let svg='';for(let i=0;i<4;i++){let yy=30+i*60;svg+=`<line x1="5" x2="725" y1="${yy}" y2="${yy}" stroke="#edf0eb"/><text x="735" y="${yy+4}" font-size="10" fill="#829188">${(high-(yy-30)/180*(high-low)).toPrecision(3)}</text>`;}
const width=Math.max(2,Math.min(12,600/(visible.length||1)));for(const [t,b] of visible){const color=b.close>=b.open?'#548f70':'#c7816a';svg+=`<line x1="${x(t)}" x2="${x(t)}" y1="${y(b.high)}" y2="${y(b.low)}" stroke="${color}"/><rect x="${x(t)-width/2}" y="${Math.min(y(b.open),y(b.close))}" width="${width}" height="${Math.max(2,Math.abs(y(b.open)-y(b.close)))}" fill="${color}"/>`;}
for(const f of state.fills.filter(f=>f.symbol===sym&&f.timestamp>=first&&f.timestamp<last+seconds)){const xx=x(Math.floor(f.timestamp/seconds)*seconds);svg+=`<text x="${xx}" y="${Math.max(14,Math.min(230,y(f.price)+(f.side==='BUY'?17:-9)))}" font-size="11" font-weight="bold" fill="${f.side==='BUY'?'#23553d':'#a34935'}">${f.side[0]}</text>`;}
if(!visible.length)svg+='<text x="220" y="120" fill="#829188" font-size="14">Start a demo or replay an imported dataset.</text>';$('chart').innerHTML=svg;$('price').textContent=price(state.last[sym]?.price);$('chart-name').textContent=sym?`${sym} · observations`:'Market observations';$('chart-start').textContent=when(first);$('chart-end').textContent=when(last);
const p=state.positions[sym],r=state.last[sym];$('coin-detail').innerHTML=r?`Liquidity: ${r.liquidity==null?'Unknown':money(r.liquidity)} · Received ${when(r.timestamp)}${p?`<br><b>Entry reason:</b> ${h(p.entry_reason)}<br>Entry ${price(p.entry)} · allocated ${money(p.cost)}`:''}${r.pool?`<br><a target="_blank" rel="noopener" href="https://dexscreener.com/solana/${encodeURIComponent(r.pool)}">Open pool on DexScreener ↗</a>`:''}${r.token?` · <a target="_blank" rel="noopener" href="https://solscan.io/token/${encodeURIComponent(r.token)}">Token on Solscan ↗</a>`:''}`:'';}
async function refreshRuns(){[runs,datasets]=await Promise.all([api('runs'),api('datasets')]);const checked=new Set([...document.querySelectorAll('.run-check:checked')].map(e=>e.value));$('runs').innerHTML=runs.map(r=>`<tr><td><input type="checkbox" class="run-check" value="${r.id}" ${checked.has(r.id)?'checked':''} aria-label="Compare ${h(r.name)}"></td><td>${h(r.name)}</td><td>${h(r.mode)}</td><td class="${sign(r.realized_pnl)}">${money(r.realized_pnl)}</td><td>${(r.max_drawdown*100).toFixed(2)}%</td><td><button data-open="${r.id}">Open</button><button data-replay="${r.dataset_id}">Replay</button></td></tr>`).join('');$('datasets').innerHTML=datasets.map(d=>`<div>${h(d.name)} · ${h(d.source)} · ${d.observations} observations</div>`).join('');const previous=$('run-dataset').value;$('run-dataset').innerHTML=datasets.filter(d=>d.observations).map(d=>`<option value="${d.id}">${h(d.name)} (${d.observations})</option>`).join('');if(previous)$('run-dataset').value=previous;}
$('toggle').onclick=()=>state&&act(state.running?'pause':'start');$('step').onclick=()=>act('step');$('symbol').onchange=chart;$('timeframe').onchange=chart;$('position-cards').onclick=e=>{const b=e.target.closest('[data-symbol]');if(b){$('symbol').value=b.dataset.symbol;chart();}};
$('new').onclick=()=>$('new-dialog').showModal();$('cancel-new').onclick=()=>$('new-dialog').close();$('new-form').onsubmit=async e=>{e.preventDefault();const mode=$('run-mode').value;$('new-dialog').close();await act('new',{mode,name:$('run-name').value,config:{size:Number($('size').value)},...(mode==='replay'?{dataset_id:$('run-dataset').value}:{})});};
$('rename').onclick=()=>{const name=prompt('Run name',state.name);if(name)act('rename',{name});};
$('runs').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open)act('open',{id:b.dataset.open});else if(b.dataset.replay){$('run-mode').value='replay';$('run-dataset').value=b.dataset.replay;$('new-dialog').showModal();}};
$('compare').onclick=()=>{const ids=[...document.querySelectorAll('.run-check:checked')].map(e=>e.value);if(ids.length!==2)return error(Error('Select exactly two runs'));const [a,b]=ids.map(id=>runs.find(r=>r.id===id));const same=a.dataset_id===b.dataset_id&&a.cutoff===b.cutoff&&a.completed&&b.completed;$('comparison').innerHTML=`<b>${h(a.name)} vs ${h(b.name)}</b><br>${same?'Same pinned dataset, both completed.':'Not a controlled comparison: dataset, coverage or completion differs.'}<br>Realized P&amp;L: ${money(a.realized_pnl)} vs ${money(b.realized_pnl)}<br>Recorded end equity: ${money(a.equity)} vs ${money(b.equity)}<br>Settings differ: ${h(Object.keys(a.config).filter(k=>a.config[k]!==b.config[k]).join(', ')||'none')}`;};
$('export').onclick=async()=>{try{const body=await api('export/'+state.id),url=URL.createObjectURL(new Blob([JSON.stringify(body,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='db-bot-'+state.id+'.json';a.click();URL.revokeObjectURL(url);}catch(e){error(e);}};
$('backup').onclick=async()=>{try{message('Backup saved: '+(await api('backup',{})).path);}catch(e){error(e);}};
$('import-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10000000)throw Error('Import limit is 10 MB per file');const result=await api('import',JSON.parse(await f.text()));message(`Imported ${result.observations} observations. Create a replay run to use them.`);await refreshRuns();}catch(e){error(e);}finally{e.target.value='';}};
function switchView(next){view=next;$('live-paper-view').hidden=next!=='live-paper';$('live-paper-tab').classList.toggle('active',next==='live-paper');$('paper-view').hidden=next!=='paper';$('wallet-view').hidden=next!=='wallet';$('discovery-view').hidden=next!=='discovery';$('discovery-tab').classList.toggle('active',next==='discovery');$('paper-tab').classList.toggle('active',next==='paper');$('wallet-tab').classList.toggle('active',next==='wallet');$('mode-badge').textContent=next==='paper'?'PAPER':next==='discovery'?'LIVE TOKENS':next==='live-paper'?'LIVE PAPER':'MAINNET ROUTES';}
$('paper-tab').onclick=()=>switchView('paper');$('wallet-tab').onclick=()=>{switchView('wallet');refreshWallet().catch(error);};
function clearQuote(){quoteGeneration++;quote=null;$('sign-swap').disabled=true;$('route').textContent='Request a fresh route for the selected wallet and amounts.';}
async function refreshWallet(){walletStatus=await api('wallet/status');if(!assetsReady){for(const id of ['input-asset','output-asset'])$(id).innerHTML=walletStatus.assets.map(a=>`<option value="${a.token}">${a.symbol}</option>`).join('');$('output-asset').value=walletStatus.assets.find(a=>a.symbol==='BONK').token;assetsReady=true;}$('execution-status').textContent=walletStatus.enabled?'Real execution is enabled. Phantom swaps require approval; enabled bot wallets sign queued trades automatically. Fees apply.':'Real execution is disabled. Read-only pool quotes work now. Enabling swaps requires restarting with --enable-live-swaps.';
$('wallet-orders').innerHTML=walletStatus.orders.map(o=>`<article><b>${h(o.status)}</b> · ${new Date(o.created*1000).toLocaleString()}${o.signature?` · <a target="_blank" rel="noopener" href="https://solscan.io/tx/${encodeURIComponent(o.signature)}">Transaction ↗</a> <button data-confirm="${o.id}">Check confirmation</button>`:''}</article>`).join('')||'No wallet orders yet.';}
$('connect-wallet').onclick=async()=>{try{walletAddress=await window.DBWallet.connect();await addConnectedWallet(walletAddress);clearQuote();$('wallet-state').textContent=walletAddress;const provider=window.DBWallet.provider();provider.on('accountChanged',()=>{walletAddress=null;clearQuote();$('wallet-state').textContent='Wallet changed — reconnect';});provider.on('disconnect',()=>{walletAddress=null;clearQuote();$('wallet-state').textContent='Wallet disconnected';});const balance=await api('wallet/balance',{wallet:walletAddress});$('wallet-balance').textContent=balance.sol.toFixed(6)+' SOL · mainnet';}catch(e){error(e);}};
$('disconnect-wallet').onclick=async()=>{try{if(walletAddress)await window.DBWallet.disconnect();}catch(e){error(e);}finally{walletAddress=null;clearQuote();$('wallet-state').textContent='Wallet disconnected';$('wallet-balance').textContent='Your paper balance is never used here.';}};
for(const id of ['input-asset','output-asset','swap-amount','swap-slippage'])$(id).onchange=clearQuote;
$('quote-form').onsubmit=async e=>{e.preventDefault();clearQuote();const generation=quoteGeneration;$('error').hidden=true;try{const received=await api('wallet/quote',{input_mint:$('input-asset').value,output_mint:$('output-asset').value,amount:$('swap-amount').value,slippage_bps:Number($('swap-slippage').value),wallet:walletAddress});if(generation!==quoteGeneration)return;quote=received;$('route').innerHTML=`<b>${h(quote.input_amount)} ${h(quote.input_symbol)} → ${h(quote.output_amount)} ${h(quote.output_symbol)}</b><br>Minimum received: <b>${h(quote.minimum_output)} ${h(quote.output_symbol)}</b><br>Slippage limit: ${(quote.slippage_bps/100).toFixed(2)}% · price impact: ${quote.price_impact_pct.toFixed(4)}%<br>Platform fee: ${h(quote.fee_bps)} bps<br>Network / priority / rent (lamports): ${quote.wallet?Object.values(quote.network_fees).map(v=>v==null?'unknown':h(v)).join(' / '):'not estimated until wallet connection'}${quote.route.map(r=>`<div class="route-hop">${h(r.venue)} · ${h(r.percent)}%<br><a href="https://solscan.io/account/${encodeURIComponent(r.pool)}" target="_blank" rel="noopener">${h(r.pool)}</a></div>`).join('')}<p>${quote.build_error?h(quote.build_error):quote.wallet?'Wallet transaction assembled. Review costs before signing.':'Connect your wallet and request a new quote to assemble a transaction.'}</p>`;await refreshWallet();}catch(e){error(e);}};
$('sign-swap').onclick=async()=>{const q=quote;if(!q||Date.now()/1000>q.expires)return error(Error('Quote expired; request a new route'));if(signing)return;signing=true;$('sign-swap').disabled=true;try{if(!confirm(`REAL MAINNET SWAP\nSell ${q.input_amount} ${q.input_symbol}\nMinimum receive ${q.minimum_output} ${q.output_symbol}\nNetwork/platform fees apply. Continue to your wallet for review?`))return;const signed=await window.DBWallet.sign(q.transaction,q.wallet);const result=await api('wallet/execute',{id:q.id,signed_transaction:signed});message(`Wallet order ${result.status}. Check confirmation before taking further action.`);clearQuote();await refreshWallet();}catch(e){clearQuote();error(e);}finally{signing=false;}};
$('wallet-orders').onclick=async e=>{const b=e.target.closest('[data-confirm]');if(!b)return;try{const r=await api('wallet/confirm',{id:b.dataset.confirm});message('Wallet order: '+r.status);await refreshWallet();}catch(e){error(e);}};
setInterval(()=>{const left=quote?Math.max(0,Math.floor(quote.expires-Date.now()/1000)):0;$('quote-age').textContent=quote?left+'s remaining':'No quote';$('sign-swap').disabled=!(!signing&&left&&quote?.transaction&&quote.wallet===walletAddress&&walletStatus?.enabled);},1000);
let polls=0;async function poll(){try{render(await api('state'));if(polls++%5===0)await refreshRuns();}catch(e){$('connection').textContent='● Disconnected';$('toggle').disabled=true;$('step').disabled=true;error(e);}finally{setTimeout(poll,1000);}}poll();refreshWallet().catch(error);

async function refreshChain(){const c=await api('chain/status');$('chain-status').textContent=c.transport+' · '+c.pending+' receipts pending. '+c.note;$('chain-watches').innerHTML=c.watches.map(w=>`<p><code>${h(w.address)}</code><br>${h(w.status)} · ${w.enabled?'Collecting':'Paused'} <button data-watch="${h(w.address)}" data-enabled="${w.enabled?'false':'true'}">${w.enabled?'Pause':'Resume'}</button></p>`).join('');$('chain-events').innerHTML=c.events.slice(0,12).map(t=>`<p><a target="_blank" rel="noopener" href="https://solscan.io/tx/${encodeURIComponent(t.signature)}">${h(t.signature.slice(0,20))}… ↗</a> · slot ${h(t.slot)} · ${t.downloaded?'Receipt stored':'Receipt pending'}</p>`).join('')||'No transactions collected yet.';}
$('watch-form').onsubmit=async e=>{e.preventDefault();try{await api('chain/watch',{address:$('watch-address').value.trim()});await refreshChain();}catch(e){error(e);}};
$('chain-watches').onclick=async e=>{const b=e.target.closest('[data-watch]');if(b)try{await api('chain/watch',{address:b.dataset.watch,enabled:b.dataset.enabled==='true'});await refreshChain();}catch(e){error(e);}};
setInterval(()=>{if(view==='wallet')refreshChain().catch(error);},5000);refreshChain().catch(error);
let managed=[],walletDialogAction='add',walletDialogId=null,portfolioBusy=false;
async function refreshManaged(){const v=await api('wallets');managed=v.wallets;const chosen=$('bot-wallet').value;$('bot-wallet').innerHTML=managed.filter(w=>w.can_sign).map(w=>`<option value="${h(w.id)}">${h(w.name)}</option>`).join('');if(chosen)$('bot-wallet').value=chosen;$('managed-wallets').innerHTML=managed.map(w=>`<article class="wallet-card"><b>${h(w.name)}</b> <span class="badge">${w.can_sign?(w.automatic?'AUTO ENABLED':w.unlocked?'UNLOCKED':'LOCKED'):'WATCH / PHANTOM'}</span><p><code>${h(w.address)}</code></p><button data-wallet-action="portfolio" data-id="${w.id}">Balance & P&L</button>${w.can_sign?` <button data-wallet-action="${w.unlocked?'lock':'unlock'}" data-id="${w.id}">${w.unlocked?'Lock':'Unlock'}</button> ${w.unlocked?`<button data-wallet-action="${w.automatic?'pause':'enable'}" data-id="${w.id}">${w.automatic?'Pause automation':'Enable automatic signing'}</button> <small>Session budget left: $${w.budget_remaining}; expires ${new Date(w.expires*1000).toLocaleTimeString()}</small>`:''} <button data-wallet-action="export" data-id="${w.id}">Recovery backup</button>`:''} <button data-wallet-action="remove" data-id="${w.id}">Remove</button></article>`).join('')||'No wallets added. Connect Phantom below, add a public address, or create an encrypted bot wallet.';$('bot-jobs').innerHTML=v.jobs.map(j=>`<p>Bot order ${h(j.id.slice(0,8))}: <b>${h(j.state)}</b>${j.error?' · '+h(j.error):''}</p>`).join('');if(walletStatus){for(const id of ['bot-input','bot-output'])if(!$(id).options.length)$(id).innerHTML=walletStatus.assets.map(a=>`<option value="${h(a.token)}">${h(a.symbol)}</option>`).join('');if($('bot-input').value===$('bot-output').value&&$('bot-output').options.length)$('bot-output').selectedIndex=1;}}
async function addConnectedWallet(address){await refreshManaged();if(!managed.some(w=>w.address===address))await api('wallets/add',{kind:'watch',name:'Phantom',address});await refreshManaged();}
function walletDialog(action,id=null){walletDialogAction=action;walletDialogId=id;$('wallet-create-fields').hidden=action!=='add';$('wallet-dialog-title').textContent=action==='add'?'Add wallet':action==='export'?'Export recovery key':'Unlock bot wallet';$('wallet-submit').textContent=action==='add'?'Save wallet':action==='export'?'Download recovery key':'Unlock for one hour';$('vault-password').value='';$('wallet-secret').value='';$('vault-message').textContent=action==='export'?'Downloads an unencrypted private-key backup. Store it securely; anyone with it can spend this wallet’s funds.':'Keys stay encrypted on disk. Unlocking keeps your passphrase in server memory for this session.';$('wallet-dialog').showModal();}
$('add-wallet').onclick=()=>walletDialog('add');$('wallet-cancel').onclick=()=>{$('wallet-dialog').close();$('vault-password').value='';$('wallet-secret').value='';};
$('wallet-form').onsubmit=async e=>{e.preventDefault();const password=$('vault-password').value;try{if(walletDialogAction==='add'){const r=await api('wallets/add',{name:$('wallet-name').value,kind:$('wallet-kind').value,address:$('wallet-address').value.trim(),secret:$('wallet-secret').value.trim()||null,password});message(r.can_sign?'Bot wallet created and locked. Export a recovery backup before funding it.':'Watch wallet added.');}else if(walletDialogAction==='unlock'){await api('wallets/unlock',{id:walletDialogId,password});message('Wallet unlocked. Automatic signing is still off until you enable it.');}else{const r=await api('wallets/export',{id:walletDialogId,password}),url=URL.createObjectURL(new Blob([r.secret+'\n'],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='bot-wallet-recovery-'+walletDialogId.slice(0,8)+'.txt';a.click();URL.revokeObjectURL(url);r.secret='';} $('wallet-dialog').close();await refreshManaged();}catch(e){error(e);}finally{$('vault-password').value='';$('wallet-secret').value='';}};
$('managed-wallets').onclick=async e=>{const b=e.target.closest('[data-wallet-action]');if(!b)return;const id=b.dataset.id,action=b.dataset.walletAction;try{if(action==='unlock'||action==='export')return walletDialog(action,id);if(action==='portfolio'){if(portfolioBusy)return;portfolioBusy=true;$('portfolio').textContent='Reading balances from Solana…';try{const p=await api('wallets/portfolio',{id});$('portfolio').innerHTML=`<h3>Wallet analysis</h3><p>${h(p.wallet)}</p><div class="portfolio-metrics"><b>${p.sol.toFixed(6)} SOL</b><span>App cash-flow realized P&L: ${p.recorded_pnl_sol===null?'Unknown / no known closes':h(p.recorded_pnl_sol)+' SOL'}</span><span>Unrealized P&L: unavailable</span><span>Recorded network fees: ${h(p.network_fees_sol)} SOL</span><span>${p.confirmed} confirmed app orders · ${p.unreconciled} unreconciled</span></div><p>Read ${new Date(p.as_of*1000).toLocaleTimeString()} · slot ${h(p.slot)}</p>${p.holdings.map(t=>`<p>${h(t.symbol)} · ${h(t.quantity)}<br><small>${h(t.mint)}</small></p>`).join('')||'<p>No nonzero token accounts.</p>'}<p>${h(p.note)}</p>`;}finally{portfolioBusy=false;}return;}if(action==='enable'){if(!confirm('Allow this bot wallet to sign and submit queued trades WITHOUT Phantom prompts for the remaining unlock session? Limits: $5 per swap, $25 input budget, plus fees.'))return;await api('wallets/enable',{id,enabled:true,acknowledge:true});}else if(action==='pause')await api('wallets/enable',{id,enabled:false});else if(action==='remove'){if(!confirm('Remove this wallet and its current encrypted key? Export a recovery backup first if it holds funds. Existing database backups can still contain encrypted keys. Submitted transactions cannot be cancelled.'))return;await api('wallets/remove',{id});$('portfolio').textContent='';}else await api('wallets/lock',{id});await refreshManaged();}catch(e){error(e);}};
$('bot-order').onsubmit=async e=>{e.preventDefault();try{await api('wallets/queue',{id:$('bot-wallet').value,input_mint:$('bot-input').value,output_mint:$('bot-output').value,amount:$('bot-amount').value,slippage_bps:100});message('Bot order queued. The enabled signer will process it without a wallet popup.');await refreshManaged();}catch(e){error(e);}};
const discoveryCards=new Map(),pendingDiscoveries=new Map(),tokenDetails=new Map(),pinnedTokens=new Set();
let discoveryBusy=false,feedBusy=false,lastDiscovery=null,discoveryStarted=false,feedGeneration=0,serverGeneration=null,coinsTab='new',marketMint=null,marketBusy=false,newCardsPaused=false;
const seenDiscoveries=new Set();
function compactSol(value){if(value==null)return 'Unavailable';const n=Number(value);return Number.isFinite(n)?new Intl.NumberFormat('en-US',{notation:'compact',maximumSignificantDigits:4}).format(n)+' SOL':'Unavailable';}
function tokenPrice(value){if(value==null)return 'Awaiting verified decimals / trade';const n=Number(value);return Number.isFinite(n)?n.toLocaleString('en-US',{maximumSignificantDigits:6})+' SOL':'Unavailable';}
function tokenMetrics(t,m){const unsupported=t.kind==='pool'&&t.quote_mint!=='So11111111111111111111111111111111111111112';return `<div class="token-metrics"><span>Price / token<b>${h(tokenPrice(m?.price_sol))}</b></span><span>Est. cap / FDV<b>${m?.fdv_sol!=null?compactSol(m.fdv_sol):'Awaiting supply / trade'}</b></span><span>Observed volume<b>${m?compactSol(m.volume_sol):'No observed trades'}</b></span><span>Buys / sells<b>${m?m.buys+' / '+m.sells:'—'}</b></span><span>Protocol fees<b>${compactSol(m?.protocol_fees_sol)}</b></span><span>Creator fees<b>${compactSol(m?.creator_fees_sol)}</b></span></div><p class="metric-coverage">${unsupported?'This pool is not SOL-quoted; live pricing is unsupported. Open GMGN.':m?'Last trade '+when(m.updated)+' · '+Math.floor(m.age_seconds||0)+'s ago'+(m.age_seconds>15?' · No fresh trade received':'')+'. Supply-based FDV; circulating cap unknown. Volume and fees cover this session only.':'Waiting for a confirmed SOL trade. No price is invented before trading begins.'}</p>`;}
function discoveryCard(t,d){const mint=t.mint||t.base_mint;return `<article class="launch-card" data-mint="${h(mint)}"><div class="coin-actions"><button data-pin="${h(mint)}" aria-pressed="${pinnedTokens.has(mint)}">${pinnedTokens.has(mint)?'Unpin':'Pin'}</button><button data-discard="${h(mint)}" ${pinnedTokens.has(mint)?'disabled':''}>Discard</button><button data-market="${h(mint)}">View live details</button></div><span class="badge">${t.kind==='token'?'PUMP.FUN TOKEN':'PUMPSWAP POOL'}</span><h3>${h(t.name||mint.slice(0,10)+'…')}${t.symbol?' ('+h(t.symbol)+')':''}</h3><p class="coin-address">${h(mint)}</p><div class="live-metrics">${tokenMetrics(t,d.metrics?.[mint])}</div><a href="https://gmgn.ai/sol/token/${encodeURIComponent(mint)}" target="_blank" rel="noopener noreferrer">Open live chart on GMGN ↗</a><p><a target="_blank" rel="noopener noreferrer" href="https://solscan.io/tx/${encodeURIComponent(t.signature)}">${t.source?'Observed trade transaction':'Creation transaction'} ↗</a></p></article>`;}
function setCoinsTab(tab){coinsTab=tab;$('launch-grid').hidden=tab!=='new';$('pinned-grid').hidden=tab!=='pinned';$('new-coins-tab').classList.toggle('active',tab==='new');$('pinned-coins-tab').classList.toggle('active',tab==='pinned');updateFeedControls();}
function updateFeedControls(){ $('pinned-coins-tab').textContent='Pinned coins ('+pinnedTokens.size+')';$('new-coins-tab').textContent='Live coins ('+[...discoveryCards.keys()].filter(m=>!pinnedTokens.has(m)).length+')';$('refresh-token-cards').textContent='Load new tokens ('+pendingDiscoveries.size+')';$('refresh-token-cards').disabled=feedBusy||newCardsPaused||!pendingDiscoveries.size;$('pause-new-cards').textContent=newCardsPaused?'Resume new cards':'Pause new cards';$('pause-new-cards').setAttribute('aria-pressed',String(newCardsPaused));$('new-cards-status').textContent=newCardsPaused?'New cards paused. Existing coin data and background scanning continue. Pin coins to protect them from expiry.':'Background scanning is active, including while you follow other coins. Use Load new tokens to display arrivals.';$('clear-token-cards').disabled=feedBusy;$('coins-empty').textContent=coinsTab==='pinned'&&!pinnedTokens.size?'Pin a coin to keep it here through Clear.':coinsTab==='new'&&!$('launch-grid').children.length?'Waiting for fresh launches. Use Load new tokens when they arrive.':'';}
function addCard(mint,t,highlight=false){const template=document.createElement('template');template.innerHTML=discoveryCard(t,lastDiscovery||{});const card=template.content.firstElementChild;card.classList.toggle('new-arrival',highlight);card.classList.toggle('pinned-card',pinnedTokens.has(mint));$(pinnedTokens.has(mint)?'pinned-grid':'launch-grid').appendChild(card);discoveryCards.set(mint,card);return card;}
function trimCards(){let normal=[...discoveryCards].filter(([mint])=>!pinnedTokens.has(mint));while(normal.length>120){const [mint,card]=normal.shift();card.remove();discoveryCards.delete(mint);tokenDetails.delete(mint);}}
function applyDiscovery(d){
 if(serverGeneration!==null&&serverGeneration!==d.generation){for(const card of discoveryCards.values())card.remove();discoveryCards.clear();pendingDiscoveries.clear();tokenDetails.clear();seenDiscoveries.clear();marketMint=null;$('live-market').hidden=true;discoveryStarted=false;}
 const storage=d.storage;if(storage)$('live-storage').textContent='Live cache: '+(storage.used_bytes/1048576).toFixed(2)+' MiB used / '+(storage.allocated_bytes/1048576).toFixed(2)+' MiB allocated · 0 bytes on disk · up to '+storage.max_tokens+' coins / 12,000 trades. Unpinned coins expire after 15 minutes. This measures SQLite pages, not total app RAM.';
 serverGeneration=d.generation;lastDiscovery=d;pinnedTokens.clear();for(const mint of d.pins||[])pinnedTokens.add(mint);
 const initial=!discoveryStarted;discoveryStarted=true;const present=new Set();
 for(const t of [...d.events].reverse()){
  const mint=t.mint||t.base_mint;present.add(mint);const previous=tokenDetails.get(mint);const details={...t,name:t.name||previous?.name,symbol:t.symbol||previous?.symbol};tokenDetails.set(mint,details);
  let card=discoveryCards.get(mint);
  if(!card){if((initial&&!newCardsPaused)||pinnedTokens.has(mint)){card=addCard(mint,details);pendingDiscoveries.delete(mint);}else if(!seenDiscoveries.has(mint)||pendingDiscoveries.has(mint)){pendingDiscoveries.set(mint,details);}}
  seenDiscoveries.add(mint);
  if(card){const dest=$(pinnedTokens.has(mint)?'pinned-grid':'launch-grid');if(card.parentElement!==dest)dest.appendChild(card);card.querySelector('.live-metrics').innerHTML=tokenMetrics(details,d.metrics?.[mint]);const pin=card.querySelector('[data-pin]');pin.textContent=pinnedTokens.has(mint)?'Unpin':'Pin';pin.setAttribute('aria-pressed',pinnedTokens.has(mint));card.classList.toggle('pinned-card',pinnedTokens.has(mint));card.querySelector('[data-discard]').disabled=pinnedTokens.has(mint);}
 }
 for(const [mint,card] of discoveryCards)if(!present.has(mint)&&!pinnedTokens.has(mint)){card.remove();discoveryCards.delete(mint);}
 for(const mint of pendingDiscoveries.keys())if(!present.has(mint)||pinnedTokens.has(mint))pendingDiscoveries.delete(mint);
 for(const mint of tokenDetails.keys())if(!present.has(mint)&&!discoveryCards.has(mint))tokenDetails.delete(mint);
 while(pendingDiscoveries.size>200)pendingDiscoveries.delete(pendingDiscoveries.keys().next().value);
 while(seenDiscoveries.size>1000)seenDiscoveries.delete(seenDiscoveries.values().next().value);
 trimCards();updateFeedControls();
 $('discovery-status').textContent=d.status+' · '+d.count+' events in session RAM';$('discovery-coverage').textContent=d.coverage+' '+(d.metadata_status||'');
 if(marketMint&&!present.has(marketMint)){marketMint=null;$('live-market').hidden=true;}
 if(marketMint)renderSelectedMetrics();
}
async function refreshDiscovery(){if(discoveryBusy||feedBusy)return;discoveryBusy=true;const generation=feedGeneration;try{const d=await api('discovery');if(generation===feedGeneration)applyDiscovery(d);}finally{discoveryBusy=false;}}
$('pause-new-cards').onclick=()=>{newCardsPaused=!newCardsPaused;updateFeedControls();};
$('refresh-token-cards').onclick=()=>{if(feedBusy||newCardsPaused||!lastDiscovery)return;for(const card of discoveryCards.values())card.classList.remove('new-arrival');let last;for(const [mint,t] of [...pendingDiscoveries].slice(0,40)){if(!discoveryCards.has(mint))last=addCard(mint,t,true);pendingDiscoveries.delete(mint);}trimCards();setCoinsTab('new');last?.scrollIntoView({behavior:'smooth',block:'end'});};
$('clear-token-cards').onclick=async()=>{if(feedBusy)return;feedBusy=true;feedGeneration++;updateFeedControls();try{const d=await api('discovery/clear',{});serverGeneration=d.generation;for(const [mint,card] of discoveryCards)if(!d.pins.includes(mint)){card.remove();discoveryCards.delete(mint);}pendingDiscoveries.clear();seenDiscoveries.clear();for(const mint of tokenDetails.keys())if(!d.pins.includes(mint))tokenDetails.delete(mint);discoveryStarted=true;applyDiscovery(d);message('Unpinned cards and their live cache cleared. Pinned coins remain.');}catch(e){error(e);}finally{feedBusy=false;updateFeedControls();}};
async function coinClick(e){const discard=e.target.closest('[data-discard]');if(discard){if(feedBusy)return;feedBusy=true;feedGeneration++;try{applyDiscovery(await api('discovery/discard',{mint:discard.dataset.discard}));}catch(err){error(err);}finally{feedBusy=false;updateFeedControls();}return;}const pin=e.target.closest('[data-pin]');if(pin){if(feedBusy)return;feedBusy=true;feedGeneration++;updateFeedControls();try{const d=await api('discovery/pin',{mint:pin.dataset.pin,pinned:!pinnedTokens.has(pin.dataset.pin)});applyDiscovery(d);}catch(e){error(e);}finally{feedBusy=false;updateFeedControls();}return;}const b=e.target.closest('[data-market]');if(!b)return;marketMint=b.dataset.market;$('selected-token-name').textContent=b.closest('.launch-card').querySelector('h3').textContent;$('selected-token-link').href='https://gmgn.ai/sol/token/'+encodeURIComponent(marketMint);$('market-title').textContent=marketMint;$('live-market').hidden=false;$('market-trades').textContent='Loading observed trades…';renderSelectedMetrics();refreshMarket();$('live-market').scrollIntoView({behavior:'smooth',block:'start'});}
$('launch-grid').onclick=coinClick;$('pinned-grid').onclick=coinClick;
function renderSelectedMetrics(){const m=lastDiscovery?.metrics?.[marketMint];$('market-summary').textContent='Price: '+tokenPrice(m?.price_sol)+' · Est. cap / FDV: '+compactSol(m?.fdv_sol);$('market-stats').textContent=m?'Last observed trade '+when(m.updated)+' · '+Math.floor(m.age_seconds||0)+'s ago. Values are SOL-denominated.':'Waiting for supported trades and verified token metadata.';}
async function refreshMarket(){if(!marketMint||marketBusy||feedBusy)return;marketBusy=true;const mint=marketMint,generation=feedGeneration;try{const m=await api('market',{mint,interval:5});if(mint!==marketMint||generation!==feedGeneration)return;$('market-note').textContent=m.note;$('market-trades').innerHTML=(m.trades||[]).slice(0,8).map(t=>`<p>${h(t.side)} · ${h(t.quantity)} tokens · ${h(t.sol)} SOL · <a href="https://solscan.io/tx/${encodeURIComponent(t.signature)}" target="_blank" rel="noopener noreferrer">Transaction ↗</a></p>`).join('')||'No supported trades observed in this session yet.';}catch(e){if(mint===marketMint&&generation===feedGeneration)$('market-note').textContent=e.message;}finally{marketBusy=false;}}
$('new-coins-tab').onclick=()=>setCoinsTab('new');$('pinned-coins-tab').onclick=()=>setCoinsTab('pinned');
$('discovery-tab').onclick=()=>{switchView('discovery');refreshDiscovery().catch(error);};
setInterval(()=>{if(view==='discovery'){refreshDiscovery().catch(error);refreshMarket();}if(view==='wallet')refreshManaged().catch(error);},2000);
refreshManaged().catch(error);

let livePaperBusy=false,livePaperState=null;
const solAmount=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:6})+' SOL';
function quoteSummary(q){if(!q)return 'Sell route check: waiting for a read-only quote';if(q.status!=='quoted')return 'Route check: '+h(q.status.replaceAll('_',' '))+' · '+h(q.note||'')+'; this does not establish liquidity loss.';const amount=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:6})+' '+(q.output_unit||'SOL');return `Unsigned ${h(q.side||'SELL')} route: ${amount(q.output)} · minimum ${amount(q.minimum_output)} · impact ${Number(q.price_impact_pct).toFixed(2)}% · ${q.fresh===false||Date.now()/1000-q.checked>15?'EXPIRED':'checked '+when(q.checked)} · model difference ${q.model_difference_pct==null?'unavailable':Number(q.model_difference_pct).toFixed(2)+'%'} · ${q.same_pool?'includes observed pool':'different route'} (network/rent estimates may differ).`;}
function costSummary(c,label){return c?`${label} modeled costs: pool fees ${solAmount(c.pool_fee_sol)}, impact ${solAmount(c.impact_sol)}, slippage ${solAmount(c.slippage_sol)}, network ${solAmount(c.network_sol)}`:`${label} cost breakdown unavailable for older trade`;}
function paperCoin(t){
 const name=t.name&&t.name!==t.mint?.slice(0,10)?t.name:'Name unavailable';
 return `<a href="https://gmgn.ai/sol/token/${encodeURIComponent(t.mint)}" target="_blank" rel="noopener noreferrer">${h(name)}${t.symbol&&t.symbol!==name?' ('+h(t.symbol)+')':''} ↗</a><small class="coin-address" title="${h(t.mint)}">${h(t.mint?.slice(0,6))}…${h(t.mint?.slice(-4))}</small>`;
}
function updatePaperRows(container,items,tag='tr'){
 const existing=new Map([...container.children].map(row=>[row.dataset.tradeId,row]));
 items.forEach(({id,html},index)=>{
  id=String(id);let row=existing.get(id);
  if(!row){row=document.createElement(tag);row.dataset.tradeId=id;}
  if(row._paperMarkup!==html){
   const details=row.querySelector('details'),expanded=details?.open;
   const focused=details?.querySelector('summary')===document.activeElement;
   row.innerHTML=html;row._paperMarkup=html;
   if(expanded)row.querySelector('details').open=true;
   if(focused)row.querySelector('summary')?.focus({preventScroll:true});
  }
  if(container.children[index]!==row)container.insertBefore(row,container.children[index]||null);
  existing.delete(id);
 });
 for(const row of existing.values())row.remove();
}
function renderLivePaper(p){
 livePaperState=p;const fx=p.usd_reference?.status==='fresh'?p.usd_reference.rate:null;
 const dollars=(n,compact=false)=>n==null||!Number.isFinite(Number(n))?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:compact?'compact':'standard',maximumFractionDigits:compact?1:2}).format(n);
 const converted=n=>n==null||fx==null?null:n*fx;
 const cap=(usd,sol)=>usd!=null?dollars(usd,true):sol!=null&&fx!=null?'≈'+dollars(converted(sol),true):'—';
 const strategy=k=>({momentum:'Momentum',recovery:'Migration recovery',ml_candidate:'ML candidate',ml_control:'ML comparison baseline',opportunity:'Pool opportunities'}[k]||k);
 const positions=p.accounts.flatMap(a=>a.positions.map(x=>({...x,strategy:a.strategy})));
 $('live-paper-status').textContent=(p.running?'Bot running':'Entries paused')+(p.config?.size_usd?' · $'+p.config.size_usd+' per entry':'');$('live-paper-fx').textContent=fx?'Dollar display live · paper trades only':'USD reference unavailable · dollar values may be missing';
 $('live-paper-error').textContent=p.error||'';$('live-paper-start').disabled=p.running;$('live-paper-pause').disabled=!p.running;
 const open=p.accounts.some(a=>a.positions.length||a.pending.length);$('live-paper-new').disabled=p.running||open;$('live-paper-clear').disabled=p.running||open;
 $('live-paper-accounts').innerHTML=p.accounts.map(a=>`<article class="strategy-card"><div class="strategy-card-head"><h3>${strategy(a.strategy)}</h3><span class="desk-chip">${a.positions.length} open</span></div><span class="metric-label">Net P&amp;L · conservative</span><strong class="account-pnl ${sign(a.net_pnl_sol)}">${dollars(converted(a.net_pnl_sol))}</strong><small>${a.net_pnl_sol>=0?'+':''}${Number(a.net_pnl_sol).toFixed(4)} SOL total</small><div class="account-foot"><span>${a.closed} closed${a.writeoffs?' · '+a.writeoffs+' unresolved losses':''}</span><span>${a.max_drawdown_pct.toFixed(1)}% drawdown</span></div></article>`).join('');
 $('live-paper-open-count').textContent=positions.length+' active';
 updatePaperRows($('live-paper-positions'),positions.length?positions.map(x=>({id:p.run_id+':'+x.strategy+':'+x.mint,html:`<div class="position-head"><div>${paperCoin(x)}<span class="strategy-label">${strategy(x.strategy)}</span></div><span class="desk-chip ${x.stale?'warning':''}">${x.stale?'Price stale':'Live'}</span></div><div class="position-values"><div><span>Entry MC</span><strong>${cap(x.entry_fdv_usd,x.entry_fdv_sol)}</strong></div><div><span>Current MC</span><strong>${cap(x.current_fdv_usd,x.current_fdv_sol)}</strong></div><div><span>Unrealized P&amp;L</span><strong class="${x.pnl_usd==null?'':sign(x.pnl_usd)}">${dollars(x.pnl_usd)}</strong><small>${x.pnl_pct==null?'Waiting for fresh trade':(x.pnl_pct>=0?'+':'')+x.pnl_pct.toFixed(1)+'%'}</small></div></div><div class="exit-status"><span class="metric-label">EXIT PLAN</span><b>${h(x.status==='Open'?'Holding — watching exit rules':x.status)}</b><p>Target +${x.exit_plan?.target_pct??'—'}% · stop −${x.exit_plan?.stop_pct??'—'}% · trail ${x.exit_plan?.trail_pct??'—'}% · ${x.exit_plan?.remaining_seconds==null?'No time limit':Math.ceil(x.exit_plan.remaining_seconds)+'s left'}</p></div><div class="position-actions"><a href="https://gmgn.ai/sol/token/${encodeURIComponent(x.mint)}" target="_blank" rel="noopener noreferrer">Open chart ↗</a><button data-paper-exit="${h(x.mint)}" data-strategy="${h(x.strategy)}">Exit paper trade</button>${x.stale?`<button data-paper-exit="${h(x.mint)}" data-strategy="${h(x.strategy)}" data-write-off="true">Retire as paper loss</button>`:''}</div>`})): [{id:'empty',html:'<div class="desk-empty">No open positions. The bot is watching for qualifying entries.</div>'}],'article');
 const f=p.feed||{},counters=f.scanner_counters||{},cov=f.valuation_coverage||{},top=(p.candidates||[]).filter(d=>d.state==='eligible'||(d.features.experimental_score??0)>=65).slice(0,8);
 $('live-paper-scan-summary').textContent='Continuous rotation · early launches discarded · positions protected';$('live-paper-scan-state').textContent=p.running?'Scanning + entries':'Scanning only';
 $('live-paper-scan-metrics').innerHTML=`<div><strong>${f.pools||0}</strong><span>Pools watched</span></div><div><strong>${f.fresh_pools||0}</strong><span>Fresh data</span></div><div><strong>${top.length}</strong><span>Strong candidates</span></div><div><strong>${counters.rejected||0}</strong><span>Released</span></div><div><strong>${dollars(converted(cov.maximum_fdv_sol),true)}</strong><span>Largest fresh MC</span></div>`;
 $('live-paper-shortlist-count').textContent='('+top.length+')';
 $('live-paper-decisions').innerHTML=top.map(d=>`<tr><td>${paperCoin(d)}<small>${strategy(d.strategy)}</small></td><td>${dollars(converted(d.features.fdv_sol),true)}</td><td>${d.features.experimental_score??'—'}</td><td>${h(d.reason)}</td></tr>`).join('')||'<tr><td colspan="4">No strong candidates with fresh data yet.</td></tr>';
 const names=new Map((p.candidates||[]).map(d=>[d.mint,d]));
 $('live-paper-skipped').innerHTML=(p.decisions||[]).filter(d=>['watching','rejected','expired'].includes(d.state)).slice(0,12).map(d=>`<div><span>${h(names.get(d.mint)?.name||d.mint.slice(0,8))}<small>${strategy(d.strategy)} · ${when(d.created)}</small></span><span>${h(d.reason)}</span></div>`).join('')||'<p>No skipped decisions yet.</p>';
 updatePaperRows($('live-paper-trades'),p.trades.length?p.trades.map(t=>({id:p.run_id+':'+t.id,html:`<td>${paperCoin(t)}<small class="strategy-label">${strategy(t.strategy)}</small></td><td class="cap-cell">${cap(t.entry_fdv_usd,t.entry_fdv_sol)}</td><td class="cap-cell">${cap(t.exit_fdv_usd,t.exit_fdv_sol)}</td><td class="${sign(t.pnl_sol)}">${t.pnl_usd==null&&fx!=null?'≈':''}${dollars(t.pnl_usd??converted(t.pnl_sol))}</td><td>${h(t.exit_reason)}<details class="trade-mini"><summary>Details</summary><p>${Math.round(t.holding_seconds??t.exit_time-t.entry_time)}s held · signal to entry ${t.signal_to_entry_seconds==null?'—':t.signal_to_entry_seconds.toFixed(1)+'s'} · entry move ${t.entry_move_pct==null?'—':t.entry_move_pct.toFixed(1)+'%'}</p><p>Before queue ${t.entry_wait_before_queue_seconds==null?'—':t.entry_wait_before_queue_seconds.toFixed(1)+'s'} · queued to fill ${t.entry_delay_seconds==null?'—':t.entry_delay_seconds.toFixed(1)+'s'} · event processing ${t.entry_event_to_evaluation_seconds==null?'—':Math.round(t.entry_event_to_evaluation_seconds*1000)+'ms'}</p><p>${h(t.entry_reason)} · ${t.blocked_exit_attempts||0} blocked exits</p></details></td>`})): [{id:'empty',html:'<td colspan="5" class="desk-empty">Closed trades will appear here.</td>'}]);
 $('live-paper-analysis').innerHTML=(p.analysis||[]).map(a=>`<div class="analysis-row"><b>${strategy(a.strategy)}</b><span>${a.trades} trades</span><span>${a.win_rate_pct==null?'—':a.win_rate_pct.toFixed(0)+'%'} win rate</span><span>Avg win ${dollars(converted(a.average_win_sol))}</span><span>Avg loss ${dollars(converted(a.average_loss_sol))}</span></div>`).join('')+'<p>Entry ceiling: +10% from the qualifying signal; modeled fill checks may reject sooner. Learning filters are evaluated separately in the paper-only lab.</p>';
 const lab=p.learning||{},ml=lab.models||{};
 const mlStatus={collecting:'Collecting outcomes',training:'Training locally',paper_candidate:'Ready for paper comparison',validation_rejected:'Did not pass later-data test',insufficient_split:'Needs more independent coins',needs_wins_and_losses:'Needs wins and losses',needs_both_barriers:'Needs target and non-target outcomes',calibration_failed:'Calibration could not fit; waiting for more data',interrupted:'Training interrupted; will retry',trainer_failed:'Trainer failed; check local runtime',trainer_timeout:'Trainer time limit reached',trainer_memory_limit:'Trainer memory limit reached',trainer_result_invalid:'Model validation failed'};
 $('live-paper-learning').innerHTML=`<p><b>XGBoost learning lab</b> · paper only</p>`+(ml.progress||[]).map(v=>`<div class="analysis-row"><b>${strategy(v.strategy)}</b><span>${h(mlStatus[v.status]||v.status)}</span><span>${v.trades} / ${ml.minimum_trades} ${h(ml.unit||'trades')}</span><span>${v.coins} / ${ml.minimum_coins} coins</span></div>`).join('');
 if(ml.trial)$('live-paper-learning').innerHTML+=`<p>Testing ${h(ml.trial.id.slice(0,8))} on ${strategy(ml.trial.strategy)}. Candidate and comparison baseline have separate balances, the same start time and the same risk limits.</p>`;
 $('live-paper-learning').innerHTML+=(ml.comparisons||[]).map(v=>`<div class="analysis-row"><b>Completed ${h(v.id.slice(0,8))}</b><span>ML ${dollars(converted(v.accounts.ml_candidate.net_pnl_sol))}</span><span>Baseline ${dollars(converted(v.accounts.ml_control.net_pnl_sol))}</span><span>No automatic promotion</span></div>`).join('');
 if(lab.error)$('live-paper-learning').innerHTML+='<p class="warning">'+h(lab.error)+'</p>';
 const obs=p.opportunities||{};
 if(obs.error)$('live-paper-learning').innerHTML+='<p class="warning">'+h(obs.error)+'</p>';
 $('live-paper-learning').innerHTML+=`<div class="analysis-row"><b>Scanner memory</b><span>${obs.retained_tokens||0} retained coins</span><span>${obs.labeled||0} barrier hits · ${obs.timeouts||0} observed timeouts</span><span>${obs.censored||0} incomplete paths excluded</span><span>${obs.queue_drops||0} queue drops</span></div><p>Target +25% before −12% within 60s. Separate training, calibration and later test periods. This research horizon does not impose a timed trade exit. Lower-ranked signals get 5% paper exploration; risk checks still apply. No automatic promotion.</p>`;
 $('live-paper-writeoff-count').textContent='('+(p.writeoffs||[]).length+')';
 $('live-paper-writeoffs').innerHTML=(p.writeoffs||[]).map(w=>`<div class="analysis-row"><b>${paperCoin(w)}</b><span>${strategy(w.strategy)}</span><span class="negative">${dollars(w.pnl_usd??converted(w.pnl_sol))}</span><span>No sale · unresolved</span></div>`).join('')||'<p>No unresolved paper losses.</p>';
 if((p.writeoffs||[]).length)$('live-paper-writeoffs').innerHTML+='<p>Capital remains charged. These are conservative paper write-offs, not executed sales or verified rugs. Records are kept for analysis.</p>';
 const bucketNames={exit:'Exit reason',age_seconds:'Observed age (seconds)',pool_sol:'Pool depth (SOL)',experimental_score:'Score',holder_concentration:'Holder concentration',participation:'Selection'};
 $('live-paper-postmortem').innerHTML=(p.postmortem||[]).filter(b=>b.losses>0).map(b=>`<div class="analysis-row"><b>${h(bucketNames[b.axis]||b.axis)} · ${h(b.bucket)}</b><span>${b.losses} losses / ${b.count} outcomes</span><span class="${sign(b.pnl_sol)}">${dollars(converted(b.pnl_sol))}</span></div>`).join('')||'<p>Loss breakdown appears after a loss or unresolved write-off.</p>';
 $('live-paper-postmortem').innerHTML+='<p>Groups describe observed outcomes; they do not prove what caused a loss. Wallet concentration and bundler data remain unavailable.</p>';
 const mem=p.memory||{};$('live-paper-memory').textContent=`Memory: ${((mem.used_bytes||0)/1048576).toFixed(1)} MB live cache. Automatic cleanup active.`;
 $('live-paper-storage').textContent=`Saved results: ${(p.storage.bytes/1048576).toFixed(1)} MB / ${(p.storage.max_bytes/1048576).toFixed(0)} MB.`;
 $('live-paper-version').textContent='Rules: '+p.version;$('live-paper-config').textContent='Feed: '+(f.feed_status||'Connecting')+'. '+(f.metadata_status||'');
}
async function refreshLivePaper(){if(livePaperBusy)return;livePaperBusy=true;try{renderLivePaper(await api('live-paper'));}catch(e){error(e);}finally{livePaperBusy=false;}}
async function livePaperAction(action){if(livePaperBusy)return;livePaperBusy=true;try{renderLivePaper(await api('live-paper/control',{action}));}catch(e){error(e);}finally{livePaperBusy=false;}}
$('live-paper-tab').onclick=()=>{switchView('live-paper');refreshLivePaper();};$('live-paper-start').onclick=()=>livePaperAction('start');$('live-paper-pause').onclick=()=>livePaperAction('pause');$('live-paper-new').onclick=()=>livePaperAction('new');$('live-paper-clear').onclick=()=>{if(confirm('Delete paper trades, saved learning models and comparison history, and reset virtual balances?'))livePaperAction('clear');};
$('live-paper-positions').onclick=async e=>{const b=e.target.closest('[data-paper-exit]');if(!b||livePaperBusy)return;const writeOff=b.dataset.writeOff==='true';if(writeOff&&!confirm('Retire this unresolved paper position at zero value? This books the capital as a loss without a sale or refund. A record is retained.'))return;livePaperBusy=true;try{renderLivePaper(await api('live-paper/exit',{strategy:b.dataset.strategy,mint:b.dataset.paperExit,write_off:writeOff}));}catch(err){error(err);}finally{livePaperBusy=false;}};
$('live-paper-export').onclick=async()=>{try{const data=await api('live-paper/export'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='live-paper-'+data.state.id+'.json';a.click();URL.revokeObjectURL(url);}catch(e){error(e);}};
setInterval(()=>{if(view==='live-paper')refreshLivePaper();},2000);

switchView('live-paper');refreshLivePaper();
